// src/store/slices/appointmentSlice.ts
// Aetherion Health - Appointment Redux Slice
// ============================================

import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface Appointment {
  id: string;
  patientId: string;
  patientName: string;
  doctorId: string;
  doctorName: string;
  doctorSpecialty: string;
  hospitalName: string;
  date: string;
  time: string;
  type: 'in-person' | 'video' | 'phone';
  status: 'scheduled' | 'confirmed' | 'in-progress' | 'completed' | 'cancelled' | 'no-show';
  reason: string;
  notes?: string;
  prescriptionId?: string;
  followUpDate?: string;
  amount: number;
  paymentStatus: 'pending' | 'paid' | 'refunded' | 'insurance';
  createdAt: string;
  updatedAt: string;
}

interface AppointmentState {
  appointments: Appointment[];
  selectedAppointment: Appointment | null;
  isLoading: boolean;
  error: string | null;
  filters: {
    status: string;
    type: string;
    date: string;
    search: string;
  };
  stats: {
    total: number;
    scheduled: number;
    completed: number;
    cancelled: number;
    todayCount: number;
  };
  pagination: {
    page: number;
    limit: number;
    total: number;
  };
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AppointmentState = {
  appointments: [],
  selectedAppointment: null,
  isLoading: false,
  error: null,
  filters: {
    status: 'all',
    type: 'all',
    date: '',
    search: '',
  },
  stats: {
    total: 0,
    scheduled: 0,
    completed: 0,
    cancelled: 0,
    todayCount: 0,
  },
  pagination: {
    page: 1,
    limit: 10,
    total: 0,
  },
};

// ============================================
// ASYNC THUNKS
// ============================================

