  createdAt: string;
  updatedAt: string;
}

interface AppointmentState {
  appointments: Appointment[];
  selectedAppointment: Appointment | null;
  isLoading: boolean;
  error: string | null;
  filters: {
    status: string;
    type: string;
    date: string;
    search: string;
  };
  stats: {
    total: number;
    scheduled: number;
    completed: number;
    cancelled: number;
    todayCount: number;
  };
  pagination: {
    page: number;
    limit: number;
    total: number;
  };
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AppointmentState = {
  appointments: [],
  selectedAppointment: null,
  isLoading: false,
  error: null,
  filters: {
    status: 'all',
    type: 'all',
    date: '',
    search: '',
  },
  stats: {
    total: 0,
    scheduled: 0,
    completed: 0,
    cancelled: 0,
    todayCount: 0,
  },
  pagination: {
    page: 1,
    limit: 10,
    total: 0,
  },
};

// ============================================
// ASYNC THUNKS
// ============================================

// Fetch all appointments
export const fetchAppointments = createAsyncThunk(
  'appointments/fetchAll',
  async (params: { page?: number; limit?: number; status?: string } | undefined, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // const response = await api.get('/appointments', { params });
      // return response.data;
      
      // Mock data for now
      return {
