// src/store/slices/hospitalSlice.ts
// HOSPITAL STATE MANAGEMENT

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface HospitalProfile {
  id: string;
  name: string;
  registrationNumber: string;
  type: 'government' | 'private' | 'charitable';
  phone: string;
  emergencyPhone: string;
  email: string;
  address: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
  };
  totalBeds: number;
  availableBeds: number;
  icuTotalBeds: number;
  icuAvailableBeds: number;
  emergencyServiceStatus: 'active' | 'busy' | 'unavailable';
  ambulanceCount: number;
  ambulanceAvailable: number;
  rating: number;
  isVerified: boolean;
}

export interface BedInfo {
  id: string;
  hospitalId: string;
  type: 'general' | 'icu' | 'emergency' | 'pediatric' | 'maternity';
  total: number;
  available: number;
  occupied: number;
  costPerDay: number;
}

export interface BloodStock {
  bloodGroup: string;
  units: number;
  status: 'sufficient' | 'low' | 'critical' | 'out-of-stock';
}

export interface HospitalStats {
  todayPatients: number;
  newAdmissions: number;
  discharges: number;
  emergencies: number;
  surgeries: number;
  occupancyRate: number;
}

export interface HospitalState {
  profile: HospitalProfile | null;
  bedInfo: BedInfo[];
  bloodStock: BloodStock[];
  stats: HospitalStats | null;
  doctors: any[];
  departments: any[];
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: HospitalState = {
  profile: null,
  bedInfo: [],
  bloodStock: [],
  stats: null,
  doctors: [],
  departments: [],
  isLoading: false,
  error: null,
};

// ============================================
// SLICE
// ============================================

const hospitalSlice = createSlice({
  name: 'hospital',
  initialState,
  reducers: {
    // Profile
    setHospitalProfile: (state, action: PayloadAction<HospitalProfile>) => {
      state.profile = action.payload;
    },
    updateHospitalProfile: (state, action: PayloadAction<Partial<HospitalProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },

    // Beds
    setBedInfo: (state, action: PayloadAction<BedInfo[]>) => {
      state.bedInfo = action.payload;
    },
    updateBedAvailability: (state, action: PayloadAction<{ bedId: string; available: number; occupied: number }>) => {
      state.bedInfo = state.bedInfo.map(bed =>
        bed.id === action.payload.bedId
          ? { ...bed, available: action.payload.available, occupied: action.payload.occupied }
          : bed
      );
    },

    // Blood Stock
    setBloodStock: (state, action: PayloadAction<BloodStock[]>) => {
      state.bloodStock = action.payload;
    },
    updateBloodStock: (state, action: PayloadAction<{ bloodGroup: string; units: number }>) => {
      state.bloodStock = state.bloodStock.map(bs =>
        bs.bloodGroup === action.payload.bloodGroup
          ? { ...bs, units: action.payload.units }
          : bs
      );
    },

    // Stats
    setHospitalStats: (state, action: PayloadAction<HospitalStats>) => {
      state.stats = action.payload;
    },

    // Doctors
    setDoctors: (state, action: PayloadAction<any[]>) => {
      state.doctors = action.payload;
    },
    addDoctor: (state, action: PayloadAction<any>) => {
      state.doctors.push(action.payload);
    },
    removeDoctor: (state, action: PayloadAction<string>) => {
      state.doctors = state.doctors.filter(d => d.id !== action.payload);
    },

    // Departments
    setDepartments: (state, action: PayloadAction<any[]>) => {
      state.departments = action.payload;
    },

    // Emergency Status
    setEmergencyStatus: (state, action: PayloadAction<'active' | 'busy' | 'unavailable'>) => {
      if (state.profile) {
        state.profile.emergencyServiceStatus = action.payload;
      }
    },

    // Loading & Error
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    setError: (state, action: PayloadAction<string | null>) => {
      state.error = action.payload;
    },

    // Reset
    clearHospital: () => initialState,
  },
});

export const {
  setHospitalProfile, updateHospitalProfile,
  setBedInfo, updateBedAvailability,
  setBloodStock, updateBloodStock,
  setHospitalStats, setDoctors, addDoctor, removeDoctor,
  setDepartments, setEmergencyStatus,
  setLoading, setError, clearHospital,
} = hospitalSlice.actions;

export default hospitalSlice.reducer;

// src/store/slices/pharmacySlice.ts
// PHARMACY STATE MANAGEMENT

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface PharmacyProfile {
  id: string;
  name: string;
  registrationNumber: string;
  licenseNumber: string;
  phone: string;
  email: string;
  address: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
  };
  isVerified: boolean;
  isOpen: boolean;
  is24x7: boolean;
  deliveryAvailable: boolean;
  rating: number;
  reviewCount: number;
}

export interface Medicine {
  id: string;
  name: string;
  genericName: string;
  category: string;
  type: 'prescription' | 'otc';
  stock: number;
  minStock: number;
  price: number;
  expiryDate: string;
  manufacturer: string;
  isAvailable: boolean;
}

export interface PharmacyOrder {
  id: string;
  orderNumber: string;
  customerName: string;
  items: OrderItem[];
  totalAmount: number;
  status: 'pending' | 'confirmed' | 'processing' | 'shipped' | 'delivered' | 'cancelled';
  orderDate: string;
  deliveryAddress: string;
}

export interface OrderItem {
  medicineId: string;
  medicineName: string;
  quantity: number;
  price: number;
}

export interface StockAlert {
  medicineId: string;
  medicineName: string;
  currentStock: number;
  minStock: number;
  status: 'low' | 'critical' | 'out-of-stock' | 'expired';
}

export interface PharmacyState {
  profile: PharmacyProfile | null;
  medicines: Medicine[];
  orders: PharmacyOrder[];
  stockAlerts: StockAlert[];
  totalOrders: number;
  totalRevenue: number;
  todayOrders: number;
  todayRevenue: number;
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: PharmacyState = {
  profile: null,
  medicines: [],
  orders: [],
  stockAlerts: [],
  totalOrders: 0,
  totalRevenue: 0,
  todayOrders: 0,
  todayRevenue: 0,
  isLoading: false,
  error: null,
};

// ============================================
// SLICE
// ============================================

const pharmacySlice = createSlice({
  name: 'pharmacy',
  initialState,
  reducers: {
    // Profile
    setPharmacyProfile: (state, action: PayloadAction<PharmacyProfile>) => {
      state.profile = action.payload;
    },
    updatePharmacyProfile: (state, action: PayloadAction<Partial<PharmacyProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },

    // Medicines
    setMedicines: (state, action: PayloadAction<Medicine[]>) => {
      state.medicines = action.payload;
    },
    addMedicine: (state, action: PayloadAction<Medicine>) => {
      state.medicines.push(action.payload);
    },
    updateMedicine: (state, action: PayloadAction<{ id: string; data: Partial<Medicine> }>) => {
      state.medicines = state.medicines.map(m =>
        m.id === action.payload.id ? { ...m, ...action.payload.data } : m
      );
    },
    updateMedicineStock: (state, action: PayloadAction<{ id: string; stock: number }>) => {
      state.medicines = state.medicines.map(m =>
        m.id === action.payload.id ? { ...m, stock: action.payload.stock } : m
      );
    },
    removeMedicine: (state, action: PayloadAction<string>) => {
      state.medicines = state.medicines.filter(m => m.id !== action.payload);
    },

    // Orders
    setOrders: (state, action: PayloadAction<PharmacyOrder[]>) => {
      state.orders = action.payload;
    },
    addOrder: (state, action: PayloadAction<PharmacyOrder>) => {
      state.orders.unshift(action.payload);
      state.totalOrders += 1;
      state.todayOrders += 1;
      state.totalRevenue += action.payload.totalAmount;
      state.todayRevenue += action.payload.totalAmount;
    },
    updateOrderStatus: (state, action: PayloadAction<{ id: string; status: PharmacyOrder['status'] }>) => {
      state.orders = state.orders.map(o =>
        o.id === action.payload.id ? { ...o, status: action.payload.status } : o
      );
    },

    // Stock Alerts
    setStockAlerts: (state, action: PayloadAction<StockAlert[]>) => {
      state.stockAlerts = action.payload;
    },

    // Stats
    setPharmacyStats: (state, action: PayloadAction<{
      totalOrders: number;
      totalRevenue: number;
      todayOrders: number;
      todayRevenue: number;
    }>) => {
      state.totalOrders = action.payload.totalOrders;
      state.totalRevenue = action.payload.totalRevenue;
      state.todayOrders = action.payload.todayOrders;
      state.todayRevenue = action.payload.todayRevenue;
    },

    // Loading & Error
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    setError: (state, action: PayloadAction<string | null>) => {
      state.error = action.payload;
    },

    // Reset
    clearPharmacy: () => initialState,
  },
});

export const {
  setPharmacyProfile, updatePharmacyProfile,
  setMedicines, addMedicine, updateMedicine, updateMedicineStock, removeMedicine,
  setOrders, addOrder, updateOrderStatus,
  setStockAlerts, setPharmacyStats,
  setLoading, setError, clearPharmacy,
} = pharmacySlice.actions;

export default pharmacySlice.reducer;

// src/store/slices/adminSlice.ts
// ADMIN STATE MANAGEMENT

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface AdminUser {
  id: string;
  name: string;
  email: string;
  role: 'super-admin' | 'admin' | 'moderator' | 'support';
  permissions: string[];
  lastLogin: string;
  isActive: boolean;
}

export interface SystemStats {
  totalUsers: number;
  totalDoctors: number;
  totalHospitals: number;
  totalPharmacies: number;
  totalBloodDonors: number;
  activeUsers: number;
  newUsersToday: number;
  blockedUsers: number;
}

export interface PendingVerification {
  id: string;
  type: 'doctor' | 'hospital' | 'pharmacy';
  name: string;
  submittedDate: string;
  status: 'pending' | 'approved' | 'rejected';
}

export interface AdminState {
  currentAdmin: AdminUser | null;
  stats: SystemStats | null;
  pendingVerifications: PendingVerification[];
  allUsers: any[];
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AdminState = {
  currentAdmin: null,
  stats: null,
  pendingVerifications: [],
  allUsers: [],
  isLoading: false,
  error: null,
};

// ============================================
// SLICE
// ============================================

const adminSlice = createSlice({
  name: 'admin',
  initialState,
  reducers: {
    // Admin Auth
    setCurrentAdmin: (state, action: PayloadAction<AdminUser>) => {
      state.currentAdmin = action.payload;
    },

    // Stats
    setStats: (state, action: PayloadAction<SystemStats>) => {
      state.stats = action.payload;
    },
    updateStats: (state, action: PayloadAction<Partial<SystemStats>>) => {
      if (state.stats) {
        state.stats = { ...state.stats, ...action.payload };
      }
    },

    // Pending Verifications
    setPendingVerifications: (state, action: PayloadAction<PendingVerification[]>) => {
      state.pendingVerifications = action.payload;
    },
    approveVerification: (state, action: PayloadAction<string>) => {
      state.pendingVerifications = state.pendingVerifications.map(v =>
        v.id === action.payload ? { ...v, status: 'approved' as const } : v
      );
    },
    rejectVerification: (state, action: PayloadAction<string>) => {
      state.pendingVerifications = state.pendingVerifications.map(v =>
        v.id === action.payload ? { ...v, status: 'rejected' as const } : v
      );
    },

    // Users Management
    setAllUsers: (state, action: PayloadAction<any[]>) => {
      state.allUsers = action.payload;
    },
    blockUser: (state, action: PayloadAction<string>) => {
      state.allUsers = state.allUsers.map(u =>
        u.id === action.payload ? { ...u, isActive: false } : u
      );
    },
    unblockUser: (state, action: PayloadAction<string>) => {
      state.allUsers = state.allUsers.map(u =>
        u.id === action.payload ? { ...u, isActive: true } : u
      );
    },
    deleteUser: (state, action: PayloadAction<string>) => {
      state.allUsers = state.allUsers.filter(u => u.id !== action.payload);
    },

    // Loading & Error
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    setError: (state, action: PayloadAction<string | null>) => {
      state.error = action.payload;
    },

    // Reset
    clearAdmin: () => initialState,
  },
});

export const {
  setCurrentAdmin, setStats, updateStats,
  setPendingVerifications, approveVerification, rejectVerification,
  setAllUsers, blockUser, unblockUser, deleteUser,
  setLoading, setError, clearAdmin,
} = adminSlice.actions;

export default adminSlice.reducer;

// src/store/slices/doctorSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
  DoctorProfile,
  DoctorAppointment,
  Patient,
  Prescription,
  EmergencyRequest,
  VideoConsultation,
  EarningsData,
  DoctorStats,
  PatientReport,
  TimeSlot,
} from '../doctor';

interface DoctorState {
  profile: DoctorProfile | null;
  appointments: DoctorAppointment[];
  patients: Patient[];
  prescriptions: Prescription[];
  emergencies: EmergencyRequest[];
  videoConsultations: VideoConsultation[];
  earnings: EarningsData;
  schedule: TimeSlot[];
  reports: PatientReport[];
  stats: DoctorStats;
  isLoading: boolean;
  error: string | null;
}

const initialState: DoctorState = {
  profile: null,
  appointments: [],
  patients: [],
  prescriptions: [],
  emergencies: [],
  videoConsultations: [],
  earnings: {
    today: 0,
    yesterday: 0,
    weekly: 0,
    monthly: 0,
    yearly: 0,
    totalConsultations: 0,
    completedAppointments: 0,
    cancelledAppointments: 0,
    averageRating: 0,
    earningsByDay: [],
    earningsByMonth: [],
  },
  schedule: [],
  reports: [],
  stats: {
    totalPatients: 0,
    todayAppointments: 0,
    completedToday: 0,
    pendingEmergencies: 0,
    videoConsultations: 0,
    earningsToday: 0,
    onlineStatus: false,
    totalPrescriptions: 0,
    averageConsultationTime: '15 mins',
  },
  isLoading: false,
  error: null,
};

const doctorSlice = createSlice({
  name: 'doctor',
  initialState,
  reducers: {
    setProfile: (state, action: PayloadAction<DoctorProfile>) => {
      state.profile = action.payload;
    },
    updateProfile: (state, action: PayloadAction<Partial<DoctorProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },
    setOnlineStatus: (state, action: PayloadAction<boolean>) => {
      if (state.profile) {
        state.profile.isOnline = action.payload;
        state.stats.onlineStatus = action.payload;
      }
    },
    setAppointments: (state, action: PayloadAction<DoctorAppointment[]>) => {
      state.appointments = action.payload;
      state.stats.todayAppointments = action.payload.filter(
        a => a.status === 'upcoming' || a.status === 'ongoing'
      ).length;
      state.stats.completedToday = action.payload.filter(
        a => a.status === 'completed'
      ).length;
    },
    updateAppointment: (state, action: PayloadAction<DoctorAppointment>) => {
      const index = state.appointments.findIndex(a => a.id === action.payload.id);
      if (index !== -1) {
        state.appointments[index] = action.payload;
      }
    },
    setPatients: (state, action: PayloadAction<Patient[]>) => {
      state.patients = action.payload;
      state.stats.totalPatients = action.payload.length;
    },
    addPatient: (state, action: PayloadAction<Patient>) => {
      state.patients.unshift(action.payload);
      state.stats.totalPatients++;
    },
    setPrescriptions: (state, action: PayloadAction<Prescription[]>) => {
      state.prescriptions = action.payload;
      state.stats.totalPrescriptions = action.payload.length;
    },
    addPrescription: (state, action: PayloadAction<Prescription>) => {
      state.prescriptions.unshift(action.payload);
      state.stats.totalPrescriptions++;
    },
    setEmergencies: (state, action: PayloadAction<EmergencyRequest[]>) => {
      state.emergencies = action.payload;
      state.stats.pendingEmergencies = action.payload.filter(
        e => e.status === 'pending'
      ).length;
    },
    acceptEmergency: (state, action: PayloadAction<string>) => {
      const emergency = state.emergencies.find(e => e.id === action.payload);
      if (emergency) {
        emergency.status = 'accepted';
        state.stats.pendingEmergencies = state.emergencies.filter(
          e => e.status === 'pending'
        ).length;
      }
    },
    rejectEmergency: (state, action: PayloadAction<string>) => {
      const emergency = state.emergencies.find(e => e.id === action.payload);
      if (emergency) {
        emergency.status = 'rejected';
        state.stats.pendingEmergencies = state.emergencies.filter(
          e => e.status === 'pending'
        ).length;
      }
    },
    setVideoConsultations: (state, action: PayloadAction<VideoConsultation[]>) => {
      state.videoConsultations = action.payload;
      state.stats.videoConsultations = action.payload.filter(
        v => v.status === 'waiting'
      ).length;
    },
    setEarnings: (state, action: PayloadAction<EarningsData>) => {
      state.earnings = action.payload;
      state.stats.earningsToday = action.payload.today;
    },
    setSchedule: (state, action: PayloadAction<TimeSlot[]>) => {
      state.schedule = action.payload;
    },
    updateSchedule: (state, action: PayloadAction<TimeSlot>) => {
      const index = state.schedule.findIndex(s => s.day === action.payload.day);
      if (index !== -1) {
        state.schedule[index] = action.payload;
      }
    },
    setReports: (state, action: PayloadAction<PatientReport[]>) => {
      state.reports = action.payload;
    },
    setStats: (state, action: PayloadAction<DoctorStats>) => {
      state.stats = action.payload;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    setError: (state, action: PayloadAction<string | null>) => {
      state.error = action.payload;
    },
  },
});

export const {
  setProfile, updateProfile, setOnlineStatus,
  setAppointments, updateAppointment,
  setPatients, addPatient,
  setPrescriptions, addPrescription,
  setEmergencies, acceptEmergency, rejectEmergency,
  setVideoConsultations, setEarnings,
  setSchedule, updateSchedule,
  setReports, setStats,
  setLoading, setError,
} = doctorSlice.actions;

export default doctorSlice.reducer;

// src/store/slices/clientSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
  ClientProfile,
  Appointment,
  BloodDonation,
  HealthRecommendation,
  MedicineReminder,
  EmergencyRequest,
  HealthStats,
  Prescription,
  MedicalReport,
  HealthTimelineEvent,
} from '../../types/client';

interface ClientState {
  profile: ClientProfile | null;
  appointments: Appointment[];
  bloodDonations: BloodDonation[];
  recommendations: HealthRecommendation[];
  reminders: MedicineReminder[];
  emergencyRequests: EmergencyRequest[];
  prescriptions: Prescription[];
  reports: MedicalReport[];
  timeline: HealthTimelineEvent[];
  stats: HealthStats;
  isLoading: boolean;
}

const initialState: ClientState = {
  profile: null,
  appointments: [],
  bloodDonations: [],
  recommendations: [],
  reminders: [],
  emergencyRequests: [],
  prescriptions: [],
  reports: [],
  timeline: [],
  stats: {
    upcomingAppointments: 0,
    activePrescriptions: 0,
    bloodDonations: 0,
    medicalReports: 0,
    healthScore: 85,
  },
  isLoading: false,
};

const clientSlice = createSlice({
  name: 'client',
  initialState,
  reducers: {
    setProfile: (state, action: PayloadAction<ClientProfile>) => {
      state.profile = action.payload;
    },
    updateProfile: (state, action: PayloadAction<Partial<ClientProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },
    setAppointments: (state, action: PayloadAction<Appointment[]>) => {
      state.appointments = action.payload;
      state.stats.upcomingAppointments = action.payload.filter(
        a => a.status === 'upcoming'
      ).length;
    },
    addAppointment: (state, action: PayloadAction<Appointment>) => {
      state.appointments.unshift(action.payload);
      state.stats.upcomingAppointments++;
    },
    updateAppointment: (state, action: PayloadAction<Appointment>) => {
      const index = state.appointments.findIndex(a => a.id === action.payload.id);
      if (index !== -1) {
        state.appointments[index] = action.payload;
      }
    },
    setBloodDonations: (state, action: PayloadAction<BloodDonation[]>) => {
      state.bloodDonations = action.payload;
      state.stats.bloodDonations = action.payload.length;
    },
    addBloodDonation: (state, action: PayloadAction<BloodDonation>) => {
      state.bloodDonations.unshift(action.payload);
      state.stats.bloodDonations++;
    },
    setRecommendations: (state, action: PayloadAction<HealthRecommendation[]>) => {
      state.recommendations = action.payload;
    },
    setReminders: (state, action: PayloadAction<MedicineReminder[]>) => {
      state.reminders = action.payload;
      state.stats.activePrescriptions = action.payload.filter(r => r.isActive).length;
    },
    addReminder: (state, action: PayloadAction<MedicineReminder>) => {
      state.reminders.push(action.payload);
      state.stats.activePrescriptions++;
    },
    toggleReminder: (state, action: PayloadAction<string>) => {
      const reminder = state.reminders.find(r => r.id === action.payload);
      if (reminder) {
        reminder.isActive = !reminder.isActive;
        state.stats.activePrescriptions = state.reminders.filter(r => r.isActive).length;
      }
    },
    setEmergencyRequests: (state, action: PayloadAction<EmergencyRequest[]>) => {
      state.emergencyRequests = action.payload;
    },
    addEmergencyRequest: (state, action: PayloadAction<EmergencyRequest>) => {
      state.emergencyRequests.unshift(action.payload);
    },
    setPrescriptions: (state, action: PayloadAction<Prescription[]>) => {
      state.prescriptions = action.payload;
    },
    setReports: (state, action: PayloadAction<MedicalReport[]>) => {
      state.reports = action.payload;
      state.stats.medicalReports = action.payload.length;
    },
    addReport: (state, action: PayloadAction<MedicalReport>) => {
      state.reports.unshift(action.payload);
      state.stats.medicalReports++;
    },
    setTimeline: (state, action: PayloadAction<HealthTimelineEvent[]>) => {
      state.timeline = action.payload;
    },
    setStats: (state, action: PayloadAction<HealthStats>) => {
      state.stats = action.payload;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
  },
});

export const {
  setProfile,
  updateProfile,
  setAppointments,
  addAppointment,
  updateAppointment,
  setBloodDonations,
  addBloodDonation,
  setRecommendations,
  setReminders,
  addReminder,
  toggleReminder,
  setEmergencyRequests,
  addEmergencyRequest,
  setPrescriptions,
  setReports,
  addReport,
  setTimeline,
  setStats,
  setLoading,
} = clientSlice.actions;

export default clientSlice.reducer;

// src/store/slices/uiSlice.ts
// UI STATE - Dark Mode, Sidebar, Notifications

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

export interface UIState {
  darkMode: boolean;
  sidebarExpanded: boolean;
  sidebarOpen: boolean;
  notifications: number;
  language: string;
  fontSize: 'small' | 'medium' | 'large';
}

const initialState: UIState = {
  darkMode: localStorage.getItem('darkMode') === 'true',
  sidebarExpanded: true,
  sidebarOpen: false,
  notifications: 0,
  language: localStorage.getItem('language') || 'en',
  fontSize: 'medium',
};

const uiSlice = createSlice({
  name: 'ui',
  initialState,
  reducers: {
    toggleDarkMode: (state) => {
      state.darkMode = !state.darkMode;
      localStorage.setItem('darkMode', state.darkMode.toString());
    },
    setDarkMode: (state, action: PayloadAction<boolean>) => {
      state.darkMode = action.payload;
    },
    toggleSidebar: (state) => {
      state.sidebarExpanded = !state.sidebarExpanded;
    },
    setSidebarOpen: (state, action: PayloadAction<boolean>) => {
      state.sidebarOpen = action.payload;
    },
    setNotifications: (state, action: PayloadAction<number>) => {
      state.notifications = action.payload;
    },
    incrementNotifications: (state) => {
      state.notifications += 1;
    },
    clearNotifications: (state) => {
      state.notifications = 0;
    },
    setLanguage: (state, action: PayloadAction<string>) => {
      state.language = action.payload;
      localStorage.setItem('language', action.payload);
    },
    setFontSize: (state, action: PayloadAction<'small' | 'medium' | 'large'>) => {
      state.fontSize = action.payload;
    },
  },
});

export const {
  toggleDarkMode,
  setDarkMode,
  toggleSidebar,
  setSidebarOpen,
  setNotifications,
  incrementNotifications,
  clearNotifications,
  setLanguage,
  setFontSize,
} = uiSlice.actions;

export default uiSlice.reducer;

