    icon: Hospital,
    badge: 12,
    pro: true,
  },
  {
    title: 'Doctors',
    path: '/doctors',
    icon: Stethoscope,
    badge: 45,
  },
  {
    title: 'Patients',
    path: '/patients',
    icon: Users,
  },
  {
    title: 'Appointments',
    path: '/appointments',
    icon: Calendar,
    badge: 8,
  },
  {
    title: 'Emergency',
    path: '/emergency',
    icon: Activity,
    badge: 'NEW',
  },
  {
    title: 'Pharmacy',
